from typing import List, Optional

def solve_langford(n: int, fixed: dict) -> Optional[List[int]]:
    length = 2 * n
    seq = [0] * length
    used = [False] * (n + 1)
    d = [0] * (n + 1)
    for v in range(1, n+1):
        d[v] = v + 1

    # Apply fixed, considering both directions
    for p, v in fixed.items():
        if seq[p] != 0 and seq[p] != v:
            return None
        seq[p] = v
        if used[v]:
            return None  # already used more than allowed but we'll check
        used[v] = True
        placed = False
        delta = d[v]
        for sign in [1, -1]:
            p2 = p + sign * delta
            if 0 <= p2 < length and seq[p2] == 0:
                seq[p2] = v
                placed = True
                break
        if not placed:
            # try if already placed somehow, but shouldn't
            return None

    # Check for conflicts in used
    for v in range(1,n+1):
        count = seq.count(v)
        if count > 2:
            return None
        if count == 2:
            used[v] = True
        elif count == 1:
            used[v] = False  # wait, but we set used when fixing, but if only one, error actually
    # if count==1 for any, it's error because we should have placed both
    for i in range(length):
        if seq[i] != 0:
            if seq.count(seq[i]) != 2:
                return None

    def backtrack(pos: int) -> bool:
        if pos == length:
            return True
        if seq[pos] != 0:
            return backtrack(pos + 1)
        for v in range(1, n+1):
            if used[v]:
                continue
            delta = d[v]
            p2 = pos + delta
            if p2 < length and seq[p2] == 0:
                seq[pos] = v
                seq[p2] = v
                used[v] = True
                if backtrack(pos + 1):
                    return True
                seq[pos] = 0
                seq[p2] = 0
                used[v] = False
        return False

    if backtrack(0):
        return seq
    return None

